<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Ban, CheckCircle2, Plus, RefreshCw } from 'lucide-vue-next'
import { api, apiError } from '../api/client'
import { fetchAllPages } from '../api/pagination'
import type { ApiResponse, Company, Customer, Receivable } from '../types'
import PageHeader from '../components/PageHeader.vue'
import DrawerPanel from '../components/DrawerPanel.vue'
import InlineAlert from '../components/InlineAlert.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EmptyState from '../components/EmptyState.vue'

interface Negotiation{id:string;company_id:string;customer_id:string;code:string;original_amount:string;negotiated_amount:string;installment_count:number;first_due_date:string;status:string;terms:Record<string,unknown>;approved_at?:string;created_at:string}
const items=ref<Negotiation[]>([]),companies=ref<Company[]>([]),customers=ref<Customer[]>([]),receivables=ref<Receivable[]>([]),drawer=ref(false),error=ref(''),success=ref('')
const form=reactive({company_id:'',customer_id:'',receivable_ids:[] as string[],negotiated_amount:'0',installment_count:1,first_due_date:new Date().toISOString().slice(0,10),notes:''})
const available=computed(()=>receivables.value.filter(x=>x.company_id===form.company_id&&x.customer_id===form.customer_id&&['OPEN','REGISTERED','OVERDUE','PARTIALLY_PAID'].includes(x.status)))
const original=computed(()=>available.value.filter(x=>form.receivable_ids.includes(x.id)).reduce((sum,x)=>sum+Number(x.balance),0))
const money=(v:string|number)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const negotiationNotes=(item:Negotiation)=>String(item.terms?.notes||item.terms?.note||'')
async function load(){error.value='';try{const [n,c,cu,r]=await Promise.all([api.get<ApiResponse<Negotiation[]>>('/v1/negotiations'),api.get<ApiResponse<Company[]>>('/v1/companies'),fetchAllPages<Customer>('/v1/customers'),fetchAllPages<Receivable>('/v1/receivables')]);items.value=n.data.data;companies.value=c.data.data;customers.value=cu;receivables.value=r}catch(e){error.value=apiError(e)}}
function open(){Object.assign(form,{company_id:companies.value[0]?.id||'',customer_id:customers.value[0]?.id||'',receivable_ids:[],negotiated_amount:'0',installment_count:1,first_due_date:new Date().toISOString().slice(0,10),notes:''});drawer.value=true}
async function create(){error.value='';try{await api.post('/v1/negotiations',{company_id:form.company_id,customer_id:form.customer_id,receivable_ids:form.receivable_ids,negotiated_amount:Number(form.negotiated_amount),installment_count:form.installment_count,first_due_date:form.first_due_date,terms:form.notes.trim()?{notes:form.notes.trim()}:{}});drawer.value=false;success.value='Negociação criada em rascunho.';await load()}catch(e){error.value=apiError(e)}}
async function approve(item:Negotiation){if(!confirm(`Aprovar ${item.code} e substituir os títulos por ${item.installment_count} parcelas?`))return;try{await api.post(`/v1/negotiations/${item.id}/approve`);success.value='Negociação aprovada e parcelas geradas.';await load()}catch(e){error.value=apiError(e)}}
async function cancel(item:Negotiation){const reason=prompt('Motivo do cancelamento:');if(!reason)return;try{await api.post(`/v1/negotiations/${item.id}/cancel`,null,{params:{reason}});await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Renegociação e acordos" subtitle="Consolide débitos, gere parcelas e preserve a rastreabilidade dos títulos originais."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open"><Plus :size="18"/>Nova negociação</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><div class="grid gap-5 xl:grid-cols-2"><article v-for="item in items" :key="item.id" class="card"><div class="flex items-start gap-3"><div class="flex-1"><div class="flex items-center gap-2"><h2 class="font-bold">{{item.code}}</h2><StatusBadge :status="item.status"/></div><p class="mt-1 text-xs text-slate-400">Cliente {{customers.find(x=>x.id===item.customer_id)?.name||'Não localizado'}}</p></div><button v-if="item.status==='DRAFT'" class="btn-primary px-3 py-2" @click="approve(item)"><CheckCircle2 :size="16"/>Aprovar</button><button v-if="!['CANCELLED','COMPLETED'].includes(item.status)" class="btn-secondary px-3 py-2 text-rose-600" @click="cancel(item)"><Ban :size="16"/></button></div><div class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><div class="rounded-xl bg-slate-50 p-3"><p class="text-xs text-slate-400">Original</p><p class="font-bold">{{money(item.original_amount)}}</p></div><div class="rounded-xl bg-emerald-50 p-3"><p class="text-xs text-emerald-600">Negociado</p><p class="font-bold text-emerald-800">{{money(item.negotiated_amount)}}</p></div><div class="rounded-xl bg-slate-50 p-3"><p class="text-xs text-slate-400">Parcelas</p><p class="font-bold">{{item.installment_count}}</p></div><div class="rounded-xl bg-slate-50 p-3"><p class="text-xs text-slate-400">Primeiro vencimento</p><p class="font-bold">{{new Date(item.first_due_date+'T00:00:00').toLocaleDateString('pt-BR')}}</p></div></div><p v-if="negotiationNotes(item)" class="mt-4 rounded-xl bg-slate-50 p-3 text-sm text-slate-600">{{negotiationNotes(item)}}</p></article><EmptyState v-if="!items.length" title="Nenhuma negociação"/></div><DrawerPanel :open="drawer" title="Nova negociação" width="xl" @close="drawer=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="create"><div><label class="label">Empresa</label><select v-model="form.company_id" class="select" required><option v-for="c in companies" :key="c.id" :value="c.id">{{c.trade_name||c.legal_name}}</option></select></div><div><label class="label">Cliente</label><select v-model="form.customer_id" class="select" required><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="md:col-span-2"><label class="label">Títulos de origem</label><div class="scroll-clean max-h-72 space-y-1 overflow-auto rounded-xl border border-slate-200 p-2"><label v-for="r in available" :key="r.id" class="flex items-center gap-3 rounded-lg p-2 hover:bg-slate-50"><input v-model="form.receivable_ids" type="checkbox" :value="r.id"/><span class="flex-1"><span class="block text-sm font-medium">{{r.document_number}} · {{r.description}}</span><span class="text-xs text-slate-400">Vence {{new Date(r.due_date+'T00:00:00').toLocaleDateString('pt-BR')}}</span></span><strong>{{money(r.balance)}}</strong></label><p v-if="!available.length" class="p-4 text-center text-sm text-slate-400">Nenhum título elegível para empresa/cliente.</p></div><p class="mt-2 text-right text-sm">Saldo selecionado: <strong>{{money(original)}}</strong></p></div><div><label class="label">Valor negociado</label><input v-model="form.negotiated_amount" type="number" min="0.01" step="0.01" class="input" required/></div><div><label class="label">Quantidade de parcelas</label><input v-model.number="form.installment_count" type="number" min="1" max="120" class="input" required/></div><div><label class="label">Primeiro vencimento</label><input v-model="form.first_due_date" type="date" class="input" required/></div><div class="rounded-xl bg-sky-50 p-3 text-sm text-sky-800">Parcela estimada: <strong>{{money(Number(form.negotiated_amount||0)/Math.max(1,form.installment_count))}}</strong></div><div class="md:col-span-2"><label class="label">Observações do acordo</label><textarea v-model="form.notes" class="input min-h-24" placeholder="Condições comerciais, observações e informações relevantes para o acordo."/></div><div class="md:col-span-2 flex justify-end gap-2 border-t pt-4"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary" :disabled="!form.receivable_ids.length">Criar rascunho</button></div></form></DrawerPanel></template>
